(()=>{
 const form=document.querySelector('#subscription-builder');if(!form)return;const R=globalThis.LPGRSubscriptionRules;
 const summary=document.querySelector('#subscription-summary'),schedule=document.querySelector('#subscription-schedule'),status=document.querySelector('#subscription-availability'),result=document.querySelector('#subscription-result'),submit=document.querySelector('#subscription-submit');
 let catalog=[],config={},ready=false,enabled=false,busy=false,current=null,startedAt=Date.now();
 const money=n=>new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR'}).format(n);
 const reservations=()=>[...form.querySelectorAll('[name="reserve-title"]:checked')].map(x=>Number(x.value));
 function lines(){return [...form.querySelectorAll('[name="subscription-title"]:checked')].map(box=>({number:Number(box.value),quantity:Number(form.querySelector(`[data-quantity="${box.value}"]`).value)}));}
 function update(){
  current=null;summary.textContent='';schedule.replaceChildren();document.querySelector('#reservation-summary').textContent='';submit.disabled=true;if(!ready)return;
  const selected=lines(),reserved=reservations();const billing=form.elements.billing_address;billing.required=selected.length>0;billing.disabled=!selected.length;billing.closest('label').hidden=!selected.length;document.querySelector('#recipient-fields').hidden=!selected.length;document.querySelector('#recipient-fields').disabled=!selected.length;
  if(!selected.length&&!reserved.length){summary.textContent='Choisissez vos livres pour afficher les envois prévus.';return;}
  try{current=R.quote(catalog,selected,reserved,config);}catch(error){summary.textContent=error.message;return;}
  summary.textContent=`${current.paid.length} exemplaire(s) · Livres : ${money(current.books)} · Port : ${money(current.shipping)} · Total estimatif : ${money(current.total)}`;
  for(const {month,book} of current.schedule){const row=document.createElement('li'),date=document.createElement('time');date.dateTime=month;date.textContent=R.monthLabel(month);row.append(date,document.createTextNode(' — '+book.title));schedule.append(row);}
  document.querySelector('#reservation-summary').textContent=current.reserved.length?'Réservations sans paiement, hors calendrier : '+current.reserved.map(x=>x.title).join(', '):'';submit.disabled=busy;
 }
 function request(){if(!current)throw Error('Vérifiez votre sélection de livres.');if(!form.reportValidity())return null;const values=Object.fromEntries(new FormData(form));return {...values,terms:values.terms==='on',acknowledge:values.acknowledge==='on',newsletter:values.newsletter==='on',lines:lines(),reservedIds:reservations(),expectedTotal:current.total,expectedSchedule:R.scheduleKey(current),startedAt};}
 function message(data){return R.summary(current)+`\n\nAcheteur : ${data.nom}\nE-mail : ${data.email}\nFacturation : ${data.billing_address||''}\nDestinataire : ${data.recipient_name||''}\n${data.address||''}\n${data.postal_code||''} ${data.city||''}\nMot pour la carte : ${data.card_message||''}\nCGV acceptées et demande sans paiement comprise. Infolettre : ${data.newsletter?'oui':'non'}`;}
 form.addEventListener('input',e=>{if(e.target.hasAttribute('data-quantity')){update();}});
 form.addEventListener('change',e=>{if(['subscription-title','reserve-title'].includes(e.target.name)||e.target.dataset.quantity){update();}});
 form.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;let data;try{data=request();}catch(error){result.textContent=error.message;return;}if(!data)return;if(!enabled){location.href='mailto:contact@lesplusgrandsracontes.fr?subject='+encodeURIComponent('Demande d’abonnement — facture et virement')+'&body='+encodeURIComponent(message(data));result.textContent='Votre messagerie s’ouvre avec votre récapitulatif : envoyez le message pour transmettre la demande. Vous pouvez aussi le télécharger.';return;}busy=true;submit.disabled=true;result.textContent='Envoi…';try{const r=await fetch('/api/subscription',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data),signal:AbortSignal.timeout(35000)});const answer=await r.json();if(!r.ok||answer.ok!==true)throw Error(answer.error||'Envoi non confirmé.');result.textContent=answer.message+(answer.newsletterStatus==='confirmation_sent'?' Confirmez séparément votre inscription à l’infolettre dans le message reçu.':answer.newsletterStatus==='unavailable'?' L’inscription à l’infolettre n’a pas pu être envoyée ; votre demande d’abonnement est bien transmise.':'');startedAt=Date.now();}catch(error){result.textContent=error.message+' Votre saisie est conservée.';}finally{busy=false;update();result.focus();}});
 document.querySelector('#subscription-email').addEventListener('click',()=>{try{const data=request();if(data)location.href='mailto:contact@lesplusgrandsracontes.fr?subject='+encodeURIComponent('Demande d’abonnement — facture et virement')+'&body='+encodeURIComponent(message(data));}catch(error){result.textContent=error.message;}});
 document.querySelector('#subscription-download').addEventListener('click',()=>{try{const data=request();if(!data)return;const url=URL.createObjectURL(new Blob([message(data)],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='demande-abonnement.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(error){result.textContent=error.message;}});
 Promise.all([fetch('/content.json',{cache:'no-store'}).then(r=>r.json()),fetch('/api/subscription',{cache:'no-store'}).then(r=>r.ok?r.json():{}).catch(()=>({}))]).then(([data,service])=>{catalog=data.books;config=data.subscription||{};ready=true;enabled=service.enabled===true;const selected=Number(new URLSearchParams(location.search).get('reserver'));for(const box of form.querySelectorAll('input[type=checkbox][value]'))if(Number(box.value)===selected)box.checked=true;status.textContent=enabled?'Votre demande sera transmise aux auteurs.':'Le bouton ouvre votre messagerie avec la demande préparée. Envoyez ensuite le message pour nous le transmettre.';update();}).catch(()=>status.textContent='Catalogue indisponible ; contactez contact@lesplusgrandsracontes.fr.');
})();
